import hashlib
from typing import Dict, List, Optional, Tuple

class MerkleNode:
    def __init__(self, key: str, value_hash: str, left: Optional['MerkleNode'] = None, right: Optional['MerkleNode'] = None):
        self.key = key
        self.value_hash = value_hash
        self.left = left
        self.right = right
        self.hash = self._compute_hash()

    def _compute_hash(self) -> str:
        hasher = hashlib.sha256()
        hasher.update(self.key.encode('utf-8'))
        hasher.update(self.value_hash.encode('utf-8'))
        if self.left:
            hasher.update(self.left.hash.encode('utf-8'))
        if self.right:
            hasher.update(self.right.hash.encode('utf-8'))
        return hasher.hexdigest()

class MerkleTree:
    def __init__(self, data: Dict[str, str]):
        sorted_items = sorted(data.items(), key=lambda x: x[0])
        self.root = self._build_tree(sorted_items)

    def _build_tree(self, items: List[Tuple[str, str]]) -> Optional[MerkleNode]:
        if not items:
            return None
        if len(items) == 1:
            k, v = items[0]
            v_hash = hashlib.sha256(v.encode('utf-8')).hexdigest()
            return MerkleNode(key=k, value_hash=v_hash)

        mid = len(items) // 2
        left_node = self._build_tree(items[:mid])
        right_node = self._build_tree(items[mid:])

        combined_key = f"{items[0][0]}-{items[-1][0]}"
        v_hash = hashlib.sha256(combined_key.encode('utf-8')).hexdigest()
        return MerkleNode(key=combined_key, value_hash=v_hash, left=left_node, right=right_node)

    def get_root_hash(self) -> Optional[str]:
        return self.root.hash if self.root else None

    def get_diff(self, other_root: Optional['MerkleNode'], current_node: Optional[MerkleNode], divergent_keys: List[str]) -> List[str]:
        if current_node is None and other_root is None:
            return divergent_keys
        if current_node is not None and other_root is not None and current_node.hash == other_root.hash:
            return divergent_keys

        if current_node and not other_root:
            self._collect_keys(current_node, divergent_keys)
            return divergent_keys

        if current_node and other_root:
            self.get_diff(other_root.left, current_node.left, divergent_keys)
            self.get_diff(other_root.right, current_node.right, divergent_keys)

        return divergent_keys

    def _collect_keys(self, node: Optional[MerkleNode], keys: List[str]):
        if not node:
            return
        if not node.left and not node.right:
            keys.append(node.key)
        else:
            self._collect_keys(node.left, keys)
            self._collect_keys(node.right, keys)

from typing import Dict, List, Optional
from gossipmesh.p2p.merkle import MerkleTree

class AntiEntropyEngine:
    def __init__(self, node_id: str):
        self.node_id = node_id
        self.state_store: Dict[str, str] = {}

    def set_state(self, key: str, value: str) -> None:
        self.state_store[key] = value

    def get_state(self, key: str) -> Optional[str]:
        return self.state_store.get(key)

    def get_merkle_tree(self) -> MerkleTree:
        return MerkleTree(self.state_store)

    def get_root_hash(self) -> Optional[str]:
        return self.get_merkle_tree().get_root_hash()

    def reconcile_divergence(self, peer_store: Dict[str, str]) -> List[str]:
        local_tree = self.get_merkle_tree()
        peer_tree = MerkleTree(peer_store)
        divergent_keys: List[str] = []
        return local_tree.get_diff(peer_tree.root, local_tree.root, divergent_keys)

import unittest
from gossipmesh.p2p.merkle import MerkleTree
from gossipmesh.p2p.entropy import AntiEntropyEngine

class TestMerkleAndEntropy(unittest.TestCase):
    def test_merkle_tree_identical(self):
        data = {'a': '1', 'b': '2', 'c': '3'}
        tree1 = MerkleTree(data)
        tree2 = MerkleTree(data)
        self.assertEqual(tree1.get_root_hash(), tree2.get_root_hash())

    def test_merkle_tree_different(self):
        data1 = {'a': '1', 'b': '2'}
        data2 = {'a': '1', 'b': '3'}
        tree1 = MerkleTree(data1)
        tree2 = MerkleTree(data2)
        self.assertNotEqual(tree1.get_root_hash(), tree2.get_root_hash())

    def test_anti_entropy_reconciliation(self):
        engine1 = AntiEntropyEngine('node-1')
        engine1.set_state('k1', 'v1')
        engine1.set_state('k2', 'v2')

        engine2 = AntiEntropyEngine('node-2')
        engine2.set_state('k1', 'v1')
        engine2.set_state('k2', 'v-modified')

        diffs = engine1.reconcile_divergence(engine2.state_store)
        self.assertIn('k2', diffs)

if __name__ == '__main__':
    unittest.main()
